@Entity(tableName = "habits")
data class HabitEntity(
    @PrimaryKey val id: Long,
    val name: String,
    val emoji: String,
    val createdAt: Long,
)

@Entity(tableName = "entries", foreignKeys = [ForeignKey(
    entity = HabitEntity::class, parentColumns = ["id"], childColumns = ["habitId"],
    onDelete = ForeignKey.CASCADE,
)], indices = [Index("habitId")])
data class EntryEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val habitId: Long,
    val date: Long,
)

data class HabitWithEntries(
    @Embedded val habit: HabitEntity,
    @Relation(parentColumn = "id", entityColumn = "habitId") val entries: List<EntryEntity>,
)

// Calculo de streak puro, testavel isolado
fun streak(entries: List<EntryEntity>, nowMs: Long = System.currentTimeMillis()): Int {
    val zone = ZoneId.systemDefault()
    val days = entries.map { Instant.ofEpochMilli(it.date).atZone(zone).toLocalDate() }.toSet()
    var count = 0
    var cursor = Instant.ofEpochMilli(nowMs).atZone(zone).toLocalDate()
    while (cursor in days) { count++; cursor = cursor.minusDays(1) }
    return count
}

data class HabitsUiState(
    val loading: Boolean = false,
    val habits: List<HabitCard> = emptyList(),
    val error: String? = null,
)

data class HabitCard(val id: Long, val name: String, val emoji: String, val streak: Int)

@HiltViewModel
class HabitsViewModel @Inject constructor(
    private val repo: HabitRepository,
) : ViewModel() {
    val state: StateFlow<HabitsUiState> = repo.observeWithEntries()
        .map { list -> list.map { HabitCard(it.habit.id, it.habit.name, it.habit.emoji, streak(it.entries)) } }
        .map { HabitsUiState(loading = false, habits = it) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), HabitsUiState(loading = true))

    fun checkIn(habitId: Long) = viewModelScope.launch { repo.addEntry(habitId) }
}

@Composable
fun HabitsScreen(vm: HabitsViewModel = hiltViewModel()) {
    val ui by vm.state.collectAsStateWithLifecycle()
    LazyColumn(Modifier.fillMaxSize().padding(16.dp)) {
        items(ui.habits, key = { it.id }) { card ->
            HabitRow(card = card, onCheckIn = { vm.checkIn(card.id) })
        }
    }
}

@Composable
fun HabitRow(card: HabitCard, onCheckIn: () -> Unit) {
    Row(
        verticalAlignment = Alignment.CenterVertically,
        modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
    ) {
        Text(card.emoji, fontSize = 28.sp)
        Spacer(Modifier.width(12.dp))
        Column(Modifier.weight(1f)) {
            Text(card.name, style = MaterialTheme.typography.titleMedium)
            Text("Streak: " + card.streak + " dias", style = MaterialTheme.typography.bodySmall)
        }
        FilledTonalButton(onClick = onCheckIn) { Text("Check-in") }
    }
}

